if($_SERVER['REQUEST_METHOD']==='POST'){ Csrf::requireValid(); $id=(int)($_POST['id']??0);$status=$_POST['status']??'open';if(in_array($status,['open','assigned','resolved','dismissed'],true)){$db->execute('UPDATE phpretro_user_reports SET status=?, assigned_to=?, action_notes=?, resolved_by=IF(? IN (\'resolved\',\'dismissed\'),?,resolved_by), resolved_at=IF(? IN (\'resolved\',\'dismissed\'),?,resolved_at) WHERE id=?',[$status,(int)($_POST['assigned_to']??0)?:null,trim((string)($_POST['action_notes']??'')),$status,(int)$user->id,$status,time(),$id]);AdminAudit::log($db,(int)$user->id,'report_'.$status,'user_report',$id,'Report triaged');$notice='Report updated.';}}
$rows=$db->fetchAll('SELECT r.id,r.reason,r.evidence,r.status,r.created_at,reporter.username reporter,reported.username reported FROM phpretro_user_reports r JOIN users reporter ON reporter.id=r.reporter_id JOIN users reported ON reported.id=r.reported_user_id ORDER BY r.created_at DESC LIMIT 200');$page['name']='Reports';$page['category']='users';require_once('./templates/housekeeping_header.php');
?><div class="page_title"><span class="page_name">User reports</span></div><div class="page_main"><div class="center"><?php if($notice){?><div class="clean-ok"><?php echo $e($notice);?></div><?php }?><table><tr><th>ID</th><th>Reporter</th><th>Reported</th><th>Reason</th><th>Evidence</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r){?><tr><td><?php echo(int)$r['id'];?></td><td><?php echo $e($r['reporter']);?></td><td><?php echo $e($r['reported']);?></td><td><?php echo $e($r['reason']);?></td><td><?php echo $e($r['evidence']);?></td><td><?php echo $e($r['status']);?></td><td><form method="post"><?php echo Csrf::field(); ?><input name="id" type="hidden" value="<?php echo(int)$r['id'];?>"><select name="status"><option>open</option><option>assigned</option><option>resolved</option><option>dismissed</option></select><input name="assigned_to" type="number" placeholder="staff ID"><input name="action_notes" placeholder="notes"><button>Save</button></form></td></tr><?php }?></table></div></div><?php require_once('./templates/housekeeping_footer.php');?>